    "solution": "<div class=\"p-6 bg-slate-100\">\n  <div class=\"card bg-white p-6 rounded-2xl shadow-lg max-w-sm\">\n    <h2 class=\"text-2xl font-bold text-slate-900\">ليان أحمد</h2>\n    <p class=\"role text-indigo-600 font-medium mt-1\">مطوّرة واجهات</p>\n    <span class=\"inline-block mt-4 bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full text-sm\">متاحة للعمل</span>\n  </div>\n</div>",
